<?php $title = __('Production Report'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="reports/production"><label class="muted"><?= __('From') ?></label><input type="date" name="from" value="<?= e($from) ?>"><label class="muted"><?= __('to') ?></label><input type="date" name="to" value="<?= e($to) ?>"><input name="q" placeholder="<?= e(__('Search order / product…')) ?>" value="<?= e($q) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><span style="flex:1"></span><button class="btn btn-outline no-print" type="button" onclick="window.print()">🖨 <?= __('Print') ?></button></form>
<div class="cards">
  <div class="card accent"><div class="lbl"><?= __('Orders Completed') ?></div><div class="val"><?= (int)$totOrders ?></div><div class="sub"><?= __('Period:') ?><?= date_display($from) ?> → <?= date_display($to) ?></div></div>
  <div class="card gold"><div class="lbl"><?= __('Finished Packets Produced') ?></div><div class="val"><?= qty($sumQty) ?></div></div>
  <div class="card blue"><div class="lbl"><?= __('Raw Materials Cost') ?></div><div class="val"><?= money($sumMat) ?></div></div>
  <div class="card red"><div class="lbl"><?= __('Total Production Cost') ?></div><div class="val"><?= money($sumCost) ?></div><div class="sub"><?= __('Labor + Overheads') ?><?= money($sumOut) ?></div></div>
