<div class="panel print-area"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Date') ?></th><th><?= __('Order') ?></th><th><?= __('Batch No') ?></th><th><?= __('Product') ?></th><th class="num"><?= __('Produced (Packets)') ?></th><th class="num"><?= __('RM Consumed (KG)') ?></th><th class="num"><?= __('RM Cost') ?></th><th class="num"><?= __('Labor') ?></th><th class="num"><?= __('Overhead') ?></th><th class="num"><?= __('Total Cost') ?></th><th class="num"><?= __('Cost / Packet') ?></th></tr></thead>
<tbody><?php foreach ($p['rows'] as $r): $cpu = (float)$r['qty_produced'] > 0 ? (float)$r['total_cost'] / (float)$r['qty_produced'] : 0; ?><tr><td><?= dt_display($r['completed_at']) ?></td><td class="mono"><?= e($r['order_no']) ?></td><td class="mono"><?= e($r['batch_no'] ?? '—') ?></td><td><?= e($r['sku']) ?> — <?= e($r['product']) ?><?= !empty($r['notes']) ? ' <span class="muted">· ' . e($r['notes']) . '</span>' : '' ?></td><td class="num"><?= qty($r['qty_produced']) ?></td><td class="num"><?= number_format($r['consumed_kg'], 3) ?></td><td class="num"><?= money($r['materials_cost'], false) ?></td><td class="num"><?= money($r['labor_cost'], false) ?></td><td class="num"><?= money($r['overhead_cost'], false) ?></td><td class="num"><strong><?= money($r['total_cost'], false) ?></strong></td><td class="num"><?= money($cpu, false) ?></td></tr><?php endforeach; ?><?php if (!$p['rows']): ?><tr><td colspan="11" class="muted"><?= __('No completed production in this period.') ?></td></tr><?php endif; ?></tbody></table></div>
<?= pager_html($p, 'reports/production', ['from' => $from, 'to' => $to, 'q' => $q]) ?></div>
